import string
import itertools

def to_num(s):
    x = 0
    for i in range(len(s)):
        x += ord(s[-1 - i]) * pow(256, i)
    return x

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def cipher_to_7bitvals(cipher, n=7):
    vals = []
    for i in range(0, len(cipher), 8):
        chunk = cipher[i:i+8]
        if len(chunk) < 8:
            chunk = chunk + b'\x00' * (8 - len(chunk))
        s = ''.join([chr(b) for b in chunk])
        x = to_num(s)
        vals.extend(get_vals(x, n))
    return vals

N = 7
KEYLEN = 8
FLAGCHARS = string.ascii_letters + string.digits + '{}_'
PRINTABLE = set(string.printable)

with open("/home/ctfplayer/ctf_files/ciphertext", "r") as f:
    hexdata = ''.join(line.strip() for line in f)
cipher = bytes.fromhex(hexdata)

c_vals = cipher_to_7bitvals(cipher, N)
L = len(c_vals)

# Build key table from known and unknowns, accepting printable ASCII for unknowns
# Allow '\n' at end (in case flag ends with }\n)
CAND_END = ['}', '}\n']

prefix = 'flag{'
init_flag = [None]*L
for i,c in enumerate(prefix):
    init_flag[i] = c
for e in CAND_END:
    for j, cc in enumerate(e[::-1]):
        init_flag[-1-j] = cc

# For each key-byte, try all values for key[i], keep those which yield printable flag text
cand_keys = [set() for _ in range(KEYLEN)]
for ki in range(KEYLEN):
    for k in range(128):
        ok = True
        for idx in range(ki, L, KEYLEN):
            # restriction: for known prefix/suffix, must yield correct char
            if init_flag[idx] is not None:
                plain = ord(init_flag[idx])
            else:
                p = (c_vals[idx] - k)%128
                if chr(p) not in FLAGCHARS:
                    ok = False; break
                continue
            c = c_vals[idx]
            if (c - k)%128 != plain:
                ok = False
                break
        if ok:
            cand_keys[ki].add(k)

# Try plausible combos (limit to top 3 per key-byte!)
def best_ks(cand):
    return list(cand)[:min(3, len(cand))]
for tup in itertools.product(*[best_ks(x) for x in cand_keys]):
    key = list(tup)
    candidate = []
    ok = True
    for i in range(L):
        p = (c_vals[i] - key[i%KEYLEN])%128
        ch = chr(p)
        if i < len(prefix) and ch != prefix[i]:
            ok = False; break
        if i == L-1 and ch not in ['}', '\n']:
            ok = False; break
        if ch not in FLAGCHARS:
            ok = False; break
        candidate.append(ch)
    if ok:
        print(''.join(candidate))

